def solve_no_61():
    MOD = 61
    N2 = [0] * MOD
    N3 = [0] * MOD
    for a in range(1, MOD):
        N2[a**2 % MOD] += 1
    for c in range(1, MOD):
        N3[c**3 % MOD] += 1

    f = [0] * MOD
    for k1 in range(MOD):
        if N2[k1] == 0: continue
        for k2 in range(MOD):
            if N2[k2] == 0: continue
            f[(k1 + k2) % MOD] += N2[k1] * N2[k2]

    g = [0] * MOD
    for k3 in range(MOD):
        if N3[k3] == 0: continue
        for k4 in range(MOD):
            if N3[k4] == 0: continue
            g[(k3 - k4) % MOD] += N3[k3] * N3[k4]

    total = 0
    for k in range(MOD):
        total += f[k] * g[k]
    return total

print(solve_no_61())

