def check_candidate_c_refined():
    MOD = 61
    f = [0] * MOD
    for a in range(MOD):
        for b in range(MOD):
            f[(a**2 + b**2) % MOD] += 1

    print(f"f(0) = {f[0]}")

    residues = []
    non_residues = []
    for i in range(1, MOD):
        if pow(i, (MOD-1)//2, MOD) == 1:
            residues.append(i)
        else:
            non_residues.append(i)

    res_val = f[residues[0]]
    non_res_val = f[non_residues[0]]

    print(f"f(residue) = {res_val}")
    print(f"f(non-residue) = {non_res_val}")

check_candidate_c_refined()

def solve():
    p = 61
    s2 = [0] * p
    for a in range(p):
        for b in range(p):
            s2[(a**2 + b**2) % p] += 1

    s3 = [0] * p
    for c in range(p):
        for d in range(p):
            s3[(c**3 - d**3) % p] += 1

    total = sum(s2[k] * s3[k] for k in range(p))

    print(f"S2: {s2}")
    print(f"S3: {s3}")
    print(f"Total: {total}")

solve()
